import{_ as e,o as a,c,a3 as l}from"./chunks/framework.DdpBa4_E.js";const g=JSON.parse('{"title":"console篇 - Ninja console.log （忍者打印）","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/09-console-篇-Ninja-console.log-忍者打印.md","filePath":"books/chrome-devtools/09-console-篇-Ninja-console.log-忍者打印.md","lastUpdated":1781445373000}'),n={name:"books/chrome-devtools/09-console-篇-Ninja-console.log-忍者打印.md"};function s(d,o,t,i,r,p){return a(),c("div",null,[...o[0]||(o[0]=[l('<h1 id="console篇-ninja-console-log-忍者打印" tabindex="-1">console篇 - Ninja console.log （忍者打印） <a class="header-anchor" href="#console篇-ninja-console-log-忍者打印" aria-label="Permalink to &quot;console篇 - Ninja console.log （忍者打印）&quot;">​</a></h1><p>有时你设置的断点是不是被执行了太多次？假设有一个包含 <code>200</code> 个元素的循环，但是你只对第 <code>110</code> 次循环的结果感兴趣，又或者你只对一些满足某些条件的结果感兴趣，怎么办呢？这就是我们要说的条件断点：</p><h2 id="_1-conditional-breakpoints-条件断点" tabindex="-1">1. <code>Conditional breakpoints</code> 条件断点 <a class="header-anchor" href="#_1-conditional-breakpoints-条件断点" aria-label="Permalink to &quot;1. `Conditional breakpoints` 条件断点&quot;">​</a></h2><p>这样的情况下，你可以设置一个条件断点：</p><ul><li><p>右击行号，选择 <code>Add conditional breakpoint...(添加条件断点)</code></p></li><li><p>或者右击一个已经设置的断点并且选择 <code>Edit breakpoint(编辑断点)</code></p></li><li><p>然后输入一个执行结果为 <code>true</code> 或者 <code>false</code> 的表达式（它的值其实不需要完全为 <code>true</code> 或者 <code>false</code> 尽管那个弹出框的描述是这样说的）。</p></li></ul><p>在这个表达式中你可以使用任何这段代码可以获取到的值（当前行的作用域）。</p><p>如果条件成立，这个断点就会暂停代码的执行：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/17/167b94b8f36112b7~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-the-ninja-忍者-console-log" tabindex="-1">2. The ninja（忍者） <code>console.log</code> <a class="header-anchor" href="#_2-the-ninja-忍者-console-log" aria-label="Permalink to &quot;2. The ninja（忍者） `console.log`&quot;">​</a></h2><p>得益于条件断点， <code>console.log</code> 也有了新玩法：</p><ul><li>每一个条件都必须经过判断 - 当应用执行到这一行的时候进行判断</li><li>并且如果条件返回的是 <code>falsy</code> 的值(这里的 <code>falsy</code>并非是笔误，<code>falsy</code> 指的是被判定为 <code>false</code> 的值，例如 <code>undefined</code> )，它并不会暂停..</li></ul><p>与其在你的源码的不同地方去添加 <code>console.log</code> / <code>console.table</code> / <code>console.time</code> 等等，不如你直接使用条件判断来将它们“连接”到 <code>Source</code> 面板中。 这样的话，它们会一直执行，并且当你不再需要它们的时候，在 <code>Breakpoints section</code> 会清晰的列出它们。点两下鼠标你就可以把所有的都移除，就像一堆忍者一样突然消失！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/17/167b955a1f0311fc~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><blockquote><p>这个技术在调试生产环境的问题时同样很有用，因为你通过这样的方式轻松将 <code>console logs</code> 插入到 <code>source</code> 里。</p></blockquote>',14)])])}const h=e(n,[["render",s]]);export{g as __pageData,h as default};
